.filter-ribbon { position: relative; display: grid; grid-template-columns: minmax(230px, 1.55fr) minmax(145px, .9fr) minmax(135px, .8fr) minmax(135px, .8fr) auto auto; gap: 0; background: var(--field-raised); border: 1px solid var(--line); border-radius: 8px; box-shadow: 0 10px 28px var(--shadow); z-index: 3; }
