r: var(--faint); font: 9px/1 "DM Mono", monospace; white-space: nowrap; transform: translateX(-50%); }.timeline-bar:hover .bar-hit, .timeline-bar.is-active .bar-hit { filter: brightness(1.5); transform: scaleX(1.08); }.timeline-bar:hover .bar-count, .timeline-bar.is-active .bar-count { opacity: 1; transform: translate(-50%, 0); }.timeline-bar.is-active .bar-hit { border-top: 2px solid var(--clay); background: rgba(229,161,120,.2); }.timeline-bar.is-active .bar-hit i { background: var(--clay); }.timeline-a11y { margin: 14px 0 0 29px; color: var(--faint); font-size: 11px; }

