 }.row-arrow { color: var(--lichen); font-size: 16px; transition: transform .15s; }.event-row:hover .row-arrow, .event-row.is-selected .row-arrow { transform: translateX(3px); }.show-more-button { display: block; min-height: 42px; margin: 17px auto 0; padding: 8px 13px; border: 1px solid var(--line-strong); border-radius: 3px; background: transparent; color: var(--lichen); font-size: 12px; font-weight: 700; }.show-more-button:hover { background: rgba(183,216,118,.06); }.stream-empty { padding: 45px 20px; text-align: center; }.stream-empty strong { font: 500 24px "Fraunces", serif; }.stream-empty p { color: var(--muted); font-size: 13px; }.event-skeleton { height: 76px; display: grid; grid-template-columns: 40px 1fr 130px; gap: 12px; align-items: center; border-bottom: 1px solid var(--line); }.event-skeleton span, .event-skeleton i { display: block; height: 14px; border-radius: 3px; background: linear-gradient(100deg, rgba(255,255,255,.035), rgba(255,255,255,.09), rgba(255,255,255,.035)); background-size: 200% 100%; animation: shimmer 1.3s infinite; }.event-skeleton span { width: 35px; height: 35px; border-radius: 50%; }.event-skeleton i:last-child { width: 100px; justify-self: end; }

