t: 20px; }.timeline-chart { gap: 3px; }.bar-label { font-size: 8px; }.event-row { grid-template-columns: 40px minmax(0, 1fr) 18px; gap: 8px; min-height: 74px; }.event-meta { display: none; }.event-primary strong { font-size: 13px; }.event-symbol { width: 34px; height: 34px; }.site-footer { grid-template-columns: 1fr; gap: 12px; padding: 22px 16px 28px; }.detail-actions { flex-wrap: wrap; }.detail-actions a { min-width: 100%; }.event-skeleton { grid-template-columns: 40px 1fr; }.event-skeleton i:last-child { display: none; } }
