63	function readURLState() {
64	  const params = new URLSearchParams(window.location.search);
65	  const validPeriod = ['hour', 'day', 'week', 'month'].includes(params.get('period')) ? params.get('period') : 'week';
66	  const validDepth = ['all', 'shallow', 'intermediate', 'deep'].includes(params.get('depth')) ? params.get('depth') : 'all';
67	  const validArea = ['all', 'americas', 'pacific', 'europe-africa', 'asia-oceania'].includes(params.get('area')) ? params.get('area') : 'all';
68	  const validTsunami = ['all', 'yes', 'no'].includes(params.get('tsunami')) ? params.get('tsunami') : 'all';
69	  const validReview = ['all', 'reviewed', 'automatic'].includes(params.get('review')) ? params.get('review') : 'all';
70	  const validSort = ['time', 'magnitude', 'significance', 'depth-asc', 'depth-desc'].includes(params.get('sort')) ? params.get('sort') : 'time';
71	  const minMagnitude = Math.min(7, Math.max(0, Number(params.get('m')) || 0));
72	  const alerts = (params.get('alerts') || '').split(',').filter((value) => ['green', 'yellow', 'orange', 'red', 'none'].includes(value));
73	  return {
74	    ...defaultFilters(),
75	    period: validPeriod,
76	    minMagnitude,
77	    depth: validDepth,
