106	function escapeHTML(value) {
107	  return String(value ?? '').replace(/[&<>'"]/g, (character) => ({
108	    '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;',
109	  }[character]));
