117	function normalizeFeature(feature) {
118	  const properties = feature?.properties || {};
119	  const coordinates = feature?.geometry?.coordinates || [];
120	  const longitude = asNumber(coordinates[0]);
121	  const latitude = asNumber(coordinates[1]);
