.selected-panel { min-height: 560px; padding: 18px; border: 1px solid var(--line); border-radius: 8px; background: linear-gradient(180deg, #142527, #102022); box-shadow: 0 14px 34px var(--shadow); }.panel-label-row { display: flex; justify-content: space-between; align-items: center; }.dismiss-button { width: 34px; height: 34px; border: 0; border-radius: 50%; background: transparent; color: var(--muted); font: 26px/1 Arial, sans-serif; }.dismiss-button:hover { background: rgba(255,255,255,.06); color: var(--ink); }.detail-empty { height: calc(100% - 34px); min-height: 430px; display: grid; place-content: center; justify-items: center; text-align: center; }.detail-empty strong { margin-top: 18px; font: 500 26px/1 "Fraunces", serif; }.detail-empty p { max-width: 260px; margin: 8px 0 0; color: var(--muted); font-size: 13px; line-height: 1.5; }.detail-orbit { position: relative; width: 82px; height: 82px; border: 1px solid var(--lichen-dim); border-radius: 50%; }.detail-orbit::before, .detail-orbit::after { content: ""; position: absolute; border: 1px solid rgba(183,216,118,.36); border-radius: 50%; }.detail-orbit::before { inset: 14px; }.detail-orbit::after { width: 9px; height: 9px; left: 7px; bottom: 14px; background: var(--lichen); box-shadow: 39px -36px 0 -2px var(--clay); }
